<?php
if(!defined('REDFOX_SKIP_BOTAPI_ROUTER'))define('REDFOX_SKIP_BOTAPI_ROUTER',true);
require_once __DIR__.'/../lib/Security.php';redfox_secure_session_start();require_once __DIR__.'/../config.php';require_once __DIR__.'/lib/icons.php';
$q=$pdo->prepare('SELECT * FROM admin WHERE username=? LIMIT 1');$q->execute([$_SESSION['user']??'']);$admin=$q->fetch(PDO::FETCH_ASSOC);if(!$admin){header('Location: login.php');exit;}if(($admin['rule']??'')!=='administrator'){http_response_code(403);exit('Forbidden');}$flash='';$ft='success';
if(($_SERVER['REQUEST_METHOD']??'')==='POST'){$id=(string)($_POST['operation_id']??'');$act=(string)($_POST['action']??'');try{$pdo->beginTransaction();$q=$pdo->prepare('SELECT * FROM reseller_service_operations WHERE operation_id=? FOR UPDATE');$q->execute([$id]);$op=$q->fetch(PDO::FETCH_ASSOC);if(!$op)throw new RuntimeException('عملیات یافت نشد.');if($act==='mark_succeeded'&&$op['status']==='needs_reconcile'){$pdo->prepare("UPDATE reseller_service_operations SET status='succeeded',updated_at=? WHERE operation_id=?")->execute([time(),$id]);$pdo->prepare("UPDATE invoice SET Status='active' WHERE id_invoice=?")->execute([$op['invoice_id']]);$flash='عملیات پس از بررسی دستی موفق ثبت شد.';}elseif($act==='refund'&&in_array($op['status'],['needs_reconcile','funds_reserved'],true)){if($op['status']==='funds_reserved'&&(time()-(int)$op['updated_at'])<900)throw new RuntimeException('عملیات هنوز تازه است؛ برای آزادسازی خودکار حداقل ۱۵ دقیقه صبر کنید.');$amount=(int)$op['price'];if($amount>0){$pdo->prepare('UPDATE user SET Balance=Balance+? WHERE id=?')->execute([$amount,$op['owner_reseller_id']]);$pdo->prepare('INSERT INTO reseller_wallet_ledger(from_user_id,to_user_id,amount,reason,actor_reseller_id,created_at) VALUES(?,?,?,?,?,?)')->execute(['system',$op['owner_reseller_id'],$amount,'manual_operation_refund',$admin['id_admin'],time()]);}$pdo->prepare("UPDATE reseller_service_operations SET status='refunded_manual',updated_at=? WHERE operation_id=?")->execute([time(),$id]);$flash='مبلغ به‌صورت دستی بازگردانده شد.';}else throw new RuntimeException('این اقدام برای وضعیت فعلی مجاز نیست.');$pdo->prepare('INSERT INTO audit_log(admin_user,action,entity,details,ip,created_at) VALUES(?,?,?,?,?,?)')->execute([$admin['username'],'service_operation.'.$act,$id,json_encode($op,JSON_UNESCAPED_UNICODE),redfox_client_ip(),date('c')]);$pdo->commit();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$flash=redfox_public_exception($e, 'panel/service_operations.php');$ft='error';}}
$statusLabels=['funds_reserved'=>'مبلغ رزروشده','remote_succeeded'=>'اعمال‌شده در پنل','succeeded'=>'موفق','refunded'=>'برگشت‌خورده','needs_reconcile'=>'نیازمند بررسی','refunded_manual'=>'برگشت دستی'];$actionLabels=['create'=>'ساخت سرویس','extend'=>'تمدید سرویس','extra_volume'=>'افزایش حجم','extra_time'=>'افزایش زمان'];$status=(string)($_GET['status']??'');$params=[];$where='1=1';if($status!==''){$where='status=?';$params[]=$status;}$q=$pdo->prepare("SELECT * FROM reseller_service_operations WHERE $where ORDER BY created_at DESC LIMIT 500");try{$q->execute($params);$rows=$q->fetchAll(PDO::FETCH_ASSOC);}catch(Throwable $e){$rows=[];$flash='Migration 003 اجرا نشده است.';$ft='error';}
?><!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>عملیات سرویس</title><link rel="stylesheet" href="css/theme.css"><style>.rx-f{padding:12px;border-radius:9px;margin:10px 0}.success{background:var(--color-success-soft);color:var(--color-success)}.error{background:var(--color-danger-soft);color:var(--color-danger)}code{font-size:10px}</style></head><body><section id="container"><?php include 'header.php';?><section id="main-content"><div class="wrapper"><div class="page-head"><h1 class="page-head__title">عملیات سرویس نمایندگان</h1><div class="page-head__sub">تطبیق عملیات نامطمئن بدون اجرای دوباره API پنل</div></div><?php if($flash):?><div class="rx-f <?=$ft?>"><?=htmlspecialchars($flash,ENT_QUOTES,'UTF-8')?></div><?php endif;?><div class="card"><form method="get"><select name="status" onchange="this.form.submit()"><option value="">همه</option><?php foreach(['funds_reserved','remote_succeeded','succeeded','refunded','needs_reconcile','refunded_manual'] as $s):?><option value="<?=$s?>" <?=$status===$s?'selected':''?>><?=htmlspecialchars($statusLabels[$s]??$s)?></option><?php endforeach;?></select></form><div class="table-wrap"><table class="app-table"><tr><th>شناسه</th><th>نماینده</th><th>فاکتور</th><th>عملیات</th><th>مبلغ</th><th>وضعیت</th><th>زمان</th><th>تطبیق</th></tr><?php foreach($rows as $r):?><tr><td><code><?=htmlspecialchars($r['operation_id'])?></code></td><td><?=$r['owner_reseller_id']?> (عامل <?=$r['actor_reseller_id']?>)</td><td><?=htmlspecialchars($r['invoice_id'])?></td><td><?=htmlspecialchars($actionLabels[$r['action']]??$r['action'])?> / <?=number_format((int)$r['amount'])?></td><td><?=number_format((int)$r['price'])?></td><td><span class="badge"><?=htmlspecialchars($statusLabels[$r['status']]??$r['status'])?></span></td><td><?=date('Y/m/d H:i',(int)$r['created_at'])?></td><td><?php if($r['status']==='needs_reconcile'):?><form method="post" style="display:inline"><input type="hidden" name="operation_id" value="<?=$r['operation_id']?>"><button name="action" value="mark_succeeded" class="btn btn-sm btn-success">پنل اعمال کرده</button><button name="action" value="refund" class="btn btn-sm btn-danger" onclick="return confirm('پس از بررسی پنل، مبلغ برگردد؟')">برگشت وجه</button></form><?php elseif($r['status']==='funds_reserved'):?><form method="post"><input type="hidden" name="operation_id" value="<?=$r['operation_id']?>"><button name="action" value="refund" class="btn btn-sm btn-danger">آزادسازی مبلغ</button></form><?php endif;?></td></tr><?php endforeach;?></table></div></div></div></section></section></body></html>
